-- Dedicated Hiring Operations records are intentionally removed.
-- Core assessments, submissions, invitations and account email remain intact.
-- Cancel only unsent messages generated by the removed bulk-assessment mailer.
DELETE FROM "OutboundMessage"
WHERE "status" IN ('pending', 'failed')
  AND ("subject" LIKE 'Assessment invitation: %' OR "subject" LIKE 'Reminder: %')
  AND "body" LIKE 'You are invited to %';
DROP TABLE "IntegrityReview";
DROP TABLE "AssessmentAccommodation";
DROP TABLE "AuditEvent";
